# Gera o app pessoal (raiz) a partir de tools/base.html + módulos RPG, check-in e temporada.
import os; SP=os.path.dirname(os.path.abspath(__file__))+'/'
s=open(SP+'base.html').read()
def rep(a,b,n=1):
    global s
    assert s.count(a)==n,(a[:60],s.count(a));s=s.replace(a,b)
R=lambda f:open(SP+f).read()
# recursos do celular no foco (tools/foco.*)
rep('</style></head>',R('foco.css')+'</style></head>')
rep('Ao terminar, o XP entra e a quest é marcada.</div>\n','Ao terminar, o XP entra e a quest é marcada.</div>\n'+R('foco.html'))
rep('<div class="toast" id="toast" hidden></div>',R('foco-room.html')+'<div class="toast" id="toast" hidden></div>')
rep('document.addEventListener("visibilitychange",()=>{if(!document.hidden)focusUI();});','document.addEventListener("visibilitychange",()=>{if(!document.hidden)focusUI();});\n'+R('foco.js'))
rep('</style></head>',R('rpg.css')+R('secret.css')+'</style></head>')
rep('<span class="pill" id="dayPill">0/0 hoje</span></div>','<span class="pill" id="dayPill">0/0 hoje</span><span class="pill clspill" id="clsPill" hidden></span></div>\n        <div class="sysline" id="sysLine"></div>')
rep('  <section data-tab="prog" class="panel">\n    <h2>Atributos</h2>\n    <div class="stats" id="stats"></div>\n  </section>\n','  <section data-tab="prog" class="panel" hidden>\n    <h2>Atributos</h2>\n    <div class="stats" id="stats"></div>\n  </section>\n'+R('rpg.html'))
rep('  <section data-tab="hoje" class="panel">\n    <div class="qhead"><h2>Check-in</h2>',R('rpg2.html')+'\n  <section data-tab="hoje" class="panel">\n    <div class="qhead"><h2>Como você está</h2>')
rep('      <summary>Backup do progresso</summary>','      <summary>Backup do progresso</summary>\n      <div class="row"><button type="button" class="link" id="seasonUndo" hidden>Recuperar meu progresso da temporada anterior</button></div>')
rep('\nlet saveTimer=null, SYNC="";','\n'+R('rpg.js')+R('checkin.js')+R('creator.js')+R('secret.js')+'\nlet saveTimer=null, SYNC="";')
rep('fillFocusSelect();renderReview();','fillFocusSelect();renderReview();renderRPG();crApply();crRender();setTimeout(dailyCheckin,600);')
rep('    </details>\n  </section>\n</div>','    </details>\n  </section>\n'+R('creator.html')+'</div>')
rep('Mais</button>\n</nav>','Mais</button>\n  <button type="button" data-go="criador" hidden><svg viewBox="0 0 24 24"><path d="M12 2l2.6 6.3L21 9l-5 4.4L17.5 20 12 16.6 6.5 20 8 13.4 3 9l6.4-.7z"/></svg>Criador</button>\n</nav>')
rep('let t0="hoje";try{t0=sessionStorage.getItem("asc-tab")||"hoje";}catch(e){}','let t0="hoje";try{t0=sessionStorage.getItem("asc-tab")||"hoje";}catch(e){}if(t0==="criador"&&!crOn())t0="hoje";')
s=s.replace('String(e.q).startsWith("ach:")','/^(ach|checkin|tip|dun|adm|ch):/.test(String(e.q))')
sea=R('season.js').replace('"asc-u-season"','"ascensao-season"').replace('"asc-u-prog-t1"','"ascensao-prog-t1"').replace('"asc-u-cfg"','"ascensao-cfg"')
rep('try{if(navigator.storage&&navigator.storage.persist)',sea+'\ntry{if(navigator.storage&&navigator.storage.persist)')
assert 'asc-u-' not in s.replace('asc-u-intro',''),'chave errada'
# telas enxutas: painéis secundários recolhidos, foco centralizado (tools/simple.*)
rep('</style></head>',R('simple.css')+'</style></head>')
rep('\nlet saveTimer=null, SYNC="";','\n'+R('simple.js')+'\nlet saveTimer=null, SYNC="";')
rep('</style></head>',R('mission.css')+'</style></head>')
rep('\nlet saveTimer=null, SYNC="";','\n'+R('mission.js')+'\nlet saveTimer=null, SYNC="";')
# sequência estilo Duolingo: escudo automático, marcos e aviso de risco (tools/streak.*)
rep('</style></head>',R('streak.css')+'</style></head>')
rep('\nlet saveTimer=null, SYNC="";','\n'+R('streak.js')+'\nlet saveTimer=null, SYNC="";')
# quebrar correntes (tools/chain.*)
rep('</style></head>',R('chain.css')+'</style></head>')
rep('\nlet saveTimer=null, SYNC="";','\n'+R('chain.js')+'\nlet saveTimer=null, SYNC="";')
# avatar por classe (tools/avatar.*)
rep('</style></head>',R('avatar.css')+'</style></head>')
rep('\nlet saveTimer=null, SYNC="";','\n'+R('avatar.js')+'\nlet saveTimer=null, SYNC="";')
# tarefas limpas + horário certo (tools/qtidy.*)
rep('</style></head>',R('qtidy.css')+'</style></head>')
rep('\nlet saveTimer=null, SYNC="";','\n'+R('qtidy.js')+'\nlet saveTimer=null, SYNC="";')
# jogar junto: ranking, liga, esquadrão, convites, amigos e aba Amigos (mesmo canal dos testadores)
rep('</style></head>',R('onb.css').split('.rk{')[0][:0]+'.rk{'+R('onb.css').split('.rk{')[1].split('\n.',5)[0]+'\n'+'\n'.join(l for l in R('onb.css').splitlines() if l.startswith('.rk '))+'\n'+R('league.css')+R('squad.css')+R('turma.css')+R('card.css')+'</style></head>')
rep('    </details>\n  </section>\n'+R('creator.html'),'    </details>\n  </section>\n'+R('rankroot.html')+R('creator.html'))
rep('\nlet saveTimer=null, SYNC="";','\n'+R('rankroot.js')+R('league.js')+R('squad.js')+R('sqinv.js')+R('friends.js')+R('turma.js')+R('card.js')+'\nlet saveTimer=null, SYNC="";')
# chefão da turma, baú do dia e mural/figurinhas (tools/boss.*, tools/chest.*, tools/mural.*)
rep('</style></head>',R('boss.css')+R('chest.css')+R('mural.css')+'</style></head>')
rep('\nlet saveTimer=null, SYNC="";','\n'+R('boss.js')+R('chest.js')+R('mural.js')+'\nlet saveTimer=null, SYNC="";')
open(SP+'../index.html','w').write(s)
